package br.edu.ifc.treinoecapacitacao.view;
import br.edu.ifc.treinoecapacitacao.App; import br.edu.ifc.treinoecapacitacao.model.Instituicao; import javafx.geometry.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public class TelaInstituicoes { private Stage stage; public TelaInstituicoes(Stage stage){this.stage=stage;} public Scene criarCena(){ Label titulo=new Label("Instituições");titulo.setId("tituloTreinamentos");TextField nome=new TextField(),cnpj=new TextField(),contato=new TextField();nome.setPromptText("Nome");cnpj.setPromptText("CNPJ");contato.setPromptText("Contato");GridPane form=new GridPane();form.setHgap(10);form.setVgap(10);form.getStyleClass().add("formulario");form.add(new Label("Nome:"),0,0);form.add(nome,1,0);form.add(new Label("CNPJ:"),0,1);form.add(cnpj,1,1);form.add(new Label("Contato:"),0,2);form.add(contato,1,2);ListView<Instituicao> lista=new ListView<Instituicao>(App.instituicoes);lista.setPrefHeight(220);Button cadastrar=new Button("Cadastrar");cadastrar.getStyleClass().add("botao-principal");Button voltar=new Button("Voltar");cadastrar.setOnAction(e->{if(nome.getText().isBlank()){new Alert(Alert.AlertType.WARNING,"Informe o nome da instituição.").show();return;}Instituicao i=new Instituicao(nome.getText(),cnpj.getText(),contato.getText());App.instituicoes.add(i);App.historico.add("Instituição cadastrada: "+i.getNome());nome.clear();cnpj.clear();contato.clear();});voltar.setOnAction(e->{stage.setScene(new TelaDashboard(stage).criarCena());stage.setTitle("Painel - Treinamento e Capacitação");});VBox raiz=new VBox(12,titulo,form,new HBox(8,cadastrar,voltar),lista);raiz.setPadding(new Insets(25));raiz.setAlignment(Pos.TOP_CENTER);Scene scene=new Scene(raiz,650,520);scene.getStylesheets().add("/css/style.css");return scene;} }
